 @Test void itemDefaultDepartmentIsOnlyRecommendationAndDoesNotBecomeActualUsage(){mapItem();UUID movement=movement("MANUAL",null);assertThat(jdbc.queryForObject("select financial_category_code from store_inventory_movement where id=?",String.class,movement)).isEqualTo("CLEAN_COST");assertThat(jdbc.queryForObject("select financial_department_id from store_inventory_movement where id=?",UUID.class,movement)).isNull();as(finance,"finance.review","finance.read");call(()->dimensions.classify(new FinanceSupplyDimensionService.Classification(UUID.randomUUID(),movement,"CLEAN_COST",deptB,"已核实本次由客房实际使用，非物品默认前厅")));assertThat(jdbc.queryForObject("select financial_department_id from fs_movement_finance_classification where movement_id=?",UUID.class,movement)).isEqualTo(deptB);assertThat(jdbc.queryForObject("select financial_department_id from store_resource_item where id=?",UUID.class,item)).isEqualTo(deptA);assertThat(jdbc.queryForObject("select financial_department_id from store_inventory_movement where id=?",UUID.class,movement)).isNull();}
