 @Test void independentImmutableMovementClassificationCompletesOnlyUnvoucheredActualSource(){
  UUID company=financialCompany(),book=auxiliaryBook(company,"FS_INVENTORY","COST",true);mapItem();UUID movement=movement("MANUAL",null);jdbc.update("insert into fs_inventory_event(tenant_id,movement_id,book_amount,source_amount,company_id) values(?,?,10,10,?)",T,movement,company);
  as(finance,"*");UUID event=UUID.fromString(call(()->accounting.recordSourceEvent(hotel,"FS_INVENTORY",movement,"COST",DAY,DAY,BigDecimal.TEN,"真实领用待独立实际部门",Map.of("businessTable","fs_inventory_event","businessId",movement.toString(),"companyId",company.toString(),"ruleEventKey","COST"))).get("id").toString());
  assertThat(jdbc.queryForObject("select status from fa_source_event where id=?",String.class,event)).isEqualTo("PENDING_AUXILIARY");String original=jdbc.queryForObject("select auxiliary_snapshot::text from fa_source_event where id=?",String.class,event);
  var input=new FinanceSupplyDimensionService.Classification(UUID.randomUUID(),movement,"CLEAN_COST",deptB,"实际客房原件独立核对后补充，不覆盖原流水或来源");call(()->dimensions.classify(input));call(()->dimensions.classify(input));
  assertThat(jdbc.queryForObject("select count(*) from fa_auxiliary_completion where event_id=?",Integer.class,event)).isOne();assertThat(jdbc.queryForObject("select snapshot#>>'{allocations,0,auxiliary,department,id}' from fa_auxiliary_completion where event_id=?",String.class,event)).isEqualTo(deptB.toString());assertThat(jdbc.queryForObject("select auxiliary_snapshot::text from fa_source_event where id=?",String.class,event)).isEqualTo(original);
  var completed=call(()->accounting.retrySource(event));UUID voucher=UUID.fromString(completed.get("voucherId").toString());assertThat(jdbc.queryForObject("select count(*) from fa_voucher_line where voucher_id=? and auxiliary#>>'{department,id}'=?",Integer.class,voucher,deptB.toString())).isEqualTo(2);assertThat(jdbc.queryForObject("select book_id from fa_voucher where id=?",UUID.class,voucher)).isEqualTo(book);
  assertThatThrownBy(()->jdbc.update("update fa_auxiliary_completion set snapshot='{}' where event_id=?",event)).hasMessageContaining("append-only");call(()->{jdbc.queryForObject("select set_config('app.tenant_id',?,true)",String.class,UUID.randomUUID().toString());assertThat(jdbc.queryForObject("select count(*) from fa_auxiliary_completion where event_id=?",Integer.class,event)).isZero();return null;});
 }
 @Test void actualConsumedPriceSharesCompleteBothVoucherSidesWithoutChangingCapturedEventOrDuplicatingCost(){
  UUID company=financialCompany();auxiliaryBook(company,"FS_PROCUREMENT","ADJUST_UP_CONSUMED",true);var order=sourceOrder("INVENTORY",true,BigDecimal.ONE,BigDecimal.TEN,BigDecimal.TEN);UUID receipt=sourceReceipt(order.get("order"),order.get("line"),BigDecimal.TEN,new BigDecimal("100")),rec=sourceRecognition(company,receipt,new BigDecimal("100"));as(finance,"*");
  UUID event=UUID.fromString(call(()->accounting.recordSourceEvent(hotel,"FS_PROCUREMENT",rec,"ADJUST_UP_CONSUMED_"+order.get("line"),DAY,DAY,new BigDecimal("3.00"),"实际已耗用价差，非新增费用",Map.of("businessTable","fs_recognition","businessId",rec.toString(),"companyId",company.toString(),"lineId",order.get("line").toString(),"nature","CONSUMED_PRICE_ADJUSTMENT","ruleEventKey","ADJUST_UP_CONSUMED"))).get("id").toString());String original=jdbc.queryForObject("select auxiliary_snapshot::text from fa_source_event where id=?",String.class,event);assertThat(jdbc.queryForObject("select status from fa_source_event where id=?",String.class,event)).isEqualTo("PENDING_AUXILIARY");
  var input=new FinanceSupplyDimensionService.PriceCosts(UUID.randomUUID(),event,List.of(new FinanceSupplyDimensionService.CostShare(deptA,"CLEAN_COST",BigDecimal.ONE),new FinanceSupplyDimensionService.CostShare(deptB,"CLEAN_COST",new BigDecimal("2.00"))),"前厅与客房实际受益按原件独立确认");call(()->dimensions.priceCosts(input));call(()->dimensions.priceCosts(input));UUID voucher=UUID.fromString(call(()->accounting.retrySource(event)).get("voucherId").toString());
  assertThat(jdbc.queryForObject("select count(*) from fa_voucher_line where voucher_id=?",Integer.class,voucher)).isEqualTo(4);assertThat(jdbc.queryForObject("select sum(debit) from fa_voucher_line where voucher_id=? and auxiliary#>>'{department,id}'=?",BigDecimal.class,voucher,deptA.toString())).isEqualByComparingTo("1.00");assertThat(jdbc.queryForObject("select sum(credit) from fa_voucher_line where voucher_id=? and auxiliary#>>'{department,id}'=?",BigDecimal.class,voucher,deptB.toString())).isEqualByComparingTo("2.00");assertThat(jdbc.queryForObject("select auxiliary_snapshot::text from fa_source_event where id=?",String.class,event)).isEqualTo(original);assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_id=?",Integer.class,rec)).isOne();assertThat(jdbc.queryForObject("select sum(actual) from fbu_flow where source_kind='PRICE_ADJUSTMENT' and source_id=?",BigDecimal.class,event)).isEqualByComparingTo("3.00");
 }
 @Test void classificationAfterVoucherCreationNeverRetrofitsFrozenLedgerHistory(){
  UUID company=financialCompany();auxiliaryBook(company,"FS_INVENTORY","COST",false);mapItem();UUID movement=movement("MANUAL",null);jdbc.update("insert into fs_inventory_event(tenant_id,movement_id,book_amount,source_amount,company_id) values(?,?,10,10,?)",T,movement,company);as(finance,"*");UUID event=UUID.fromString(call(()->accounting.recordSourceEvent(hotel,"FS_INVENTORY",movement,"COST",DAY,DAY,BigDecimal.TEN,"原来源已生成凭证，分类不回填历史",Map.of("businessTable","fs_inventory_event","businessId",movement.toString(),"companyId",company.toString(),"ruleEventKey","COST"))).get("id").toString());UUID voucher=jdbc.queryForObject("select voucher_id from fa_source_event where id=?",UUID.class,event);assertThat(voucher).isNotNull();String lines=jdbc.queryForObject("select jsonb_agg(auxiliary order by line_no)::text from fa_voucher_line where voucher_id=?",String.class,voucher);
  call(()->dimensions.classify(new FinanceSupplyDimensionService.Classification(UUID.randomUUID(),movement,"CLEAN_COST",deptB,"预算可记录实际分类，总账必须另走开放期重分类")));assertThat(jdbc.queryForObject("select count(*) from fa_auxiliary_completion where event_id=?",Integer.class,event)).isZero();assertThat(jdbc.queryForObject("select jsonb_agg(auxiliary order by line_no)::text from fa_voucher_line where voucher_id=?",String.class,voucher)).isEqualTo(lines);
 }
 private UUID auxiliaryBook(UUID company,String type,String event,boolean required){
  UUID book=UUID.randomUUID();as(owner,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"真实辅助核算来源账套",DAY.withDayOfMonth(1))));var governance=new FinanceLedgerGovernance(named,new TenantDatabaseContext(jdbc,true),new AccessPolicy(),accounting);
  for(String code:List.of("EXP","AP")){UUID proposal=UUID.randomUUID();as(owner,"*");call(()->governance.account(proposal,new FinanceAccountingModels.Account(book,code,code,code.equals("EXP")?"EXPENSE":"LIABILITY",code.equals("EXP")?"DEBIT":"CREDIT",code,false,true,-1,required?List.of("DEPARTMENT"):List.of()),"真实科目明确部门辅助要求"));as(finance,"*");call(()->governance.publish(proposal,new FinanceControlModels.Version(0,"独立发布实际科目"),false));}
  UUID rule=UUID.randomUUID();as(owner,"*");call(()->governance.rule(rule,new FinanceAccountingModels.Rule(book,type,event,"EXP","AP",null,true,-1),"真实经济来源映射"));as(finance,"*");call(()->governance.publish(rule,new FinanceControlModels.Version(0,"独立发布来源规则"),false));as(owner,"*");return book;
 }
 @Test void distinctRealProjectsCannotUseEachOthersReservedCostQuota(){
  UUID company=financialCompany(),a=projectContract(company),b=projectContract(company);projectBudget(a,"10.00");UUID first=projectOrder(a,"8.00",BigDecimal.ONE),other=projectOrder(b,"8.00",BigDecimal.ONE);
  assertThat(jdbc.queryForObject("select sum(inflight) from fbu_flow where hotel_id=? and project_key=?",BigDecimal.class,hotel,"CONTRACT:"+a)).isEqualByComparingTo("8.00");assertThat(jdbc.queryForObject("select sum(inflight) from fbu_flow where hotel_id=? and project_key=?",BigDecimal.class,hotel,"CONTRACT:"+b)).isEqualByComparingTo("8.00");assertThat(first).isNotEqualTo(other);assertThatThrownBy(()->projectOrder(a,"8.00",BigDecimal.ONE)).hasMessageContaining("预算不足");
 }
 @Test void oneProjectPartialFinancialAcceptanceAndReplayNeverDoubleCountCommitmentOrActual(){
  UUID company=financialCompany(),project=projectContract(company);projectBudget(project,"10.00");UUID order=projectOrder(project,"5.00",new BigDecimal("2")),line=jdbc.queryForObject("select id from procurement_line where order_id=?",UUID.class,order);as(owner,"*");call(()->procurement.purchase(order,new ProcurementModels.Purchase(UUID.randomUUID(),2,"真实供应商",DAY,owner,List.of(new ProcurementModels.Price(line,new BigDecimal("5"))))));
  UUID receipt=sourceReceipt(order,line,BigDecimal.ONE,new BigDecimal("5")),rec=sourceRecognition(company,receipt,new BigDecimal("5"));sourceEvent(rec,line,"5.00");call(()->{new FinanceBudgetBridge(named).recognition(TenantContext.require(),rec);return null;});assertThat(flowSum(order,"committed")).isEqualByComparingTo("5.00");UUID secondReceipt=sourceReceipt(order,line,BigDecimal.ONE,new BigDecimal("5")),second=sourceRecognition(company,secondReceipt,new BigDecimal("5"));sourceEvent(second,line,"5.00");call(()->{var bridge=new FinanceBudgetBridge(named);bridge.recognition(TenantContext.require(),second);bridge.recognition(TenantContext.require(),second);return null;});assertThat(flowSum(order,"committed")).isZero();assertThat(jdbc.queryForObject("select sum(actual) from fbu_flow where hotel_id=? and project_key=?",BigDecimal.class,hotel,"CONTRACT:"+project)).isEqualByComparingTo("10.00");assertThat(jdbc.queryForObject("select count(*) from fbu_flow where hotel_id=? and project_key=? and source_kind='RECEIPT'",Integer.class,hotel,"CONTRACT:"+project)).isEqualTo(2);
 }
